#include <iostream>

// Class contract exposed first via public section
class ChassisFan {
public:
    ChassisFan();
    ChassisFan(int rpm, int sizeMm);

    void turnOn();
    void turnOff();
    void setSpeed(int rpm);
    int getSpeed() const;
    int getSize() const;
    bool isRunning() const;

private:
    // Encapsulated state hidden from clients
    int speedRpm;
    int diameterMm;
    bool active;
};

ChassisFan::ChassisFan() : speedRpm(0), diameterMm(120), active(false) {}

ChassisFan::ChassisFan(int rpm, int sizeMm) 
    : speedRpm(rpm), diameterMm(sizeMm), active(true) {}

void ChassisFan::turnOn() {
    active = true;
    if (speedRpm == 0) {
        speedRpm = 1200;
    }
}

void ChassisFan::turnOff() {
    active = false;
    speedRpm = 0;
}

void ChassisFan::setSpeed(int rpm) {
    if (rpm > 0) {
        speedRpm = rpm;
        active = true;
    } else {
        turnOff();
    }
}

int ChassisFan::getSpeed() const {
    return speedRpm;
}

int ChassisFan::getSize() const {
    return diameterMm;
}

bool ChassisFan::isRunning() const {
    return active;
}

int main() {
    // The client uses the fan purely via its public contract
    ChassisFan fan(1500, 140);
    std::cout << "Fan diameter: " << fan.getSize() << " mm\n";
    std::cout << "Initial status: " << (fan.isRunning() ? "Running" : "Stopped") 
              << " at " << fan.getSpeed() << " RPM\n";

    fan.setSpeed(2000);
    std::cout << "Adjusted speed: " << fan.getSpeed() << " RPM\n";

    fan.turnOff();
    std::cout << "After shutdown: " << (fan.isRunning() ? "Running" : "Stopped") << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

// Class declaration corresponding to Loan.h
class Loan {
public:
    Loan();
    Loan(double rate, int years, double amount);

    double getAnnualInterestRate();
    int getNumberOfYears();
    double getLoanAmount();

    void setAnnualInterestRate(double rate);
    void setNumberOfYears(int years);
    void setLoanAmount(double amount);

    double getMonthlyPayment();
    double getTotalPayment();

private:
    double annualInterestRate;
    int numberOfYears;
    double loanAmount;
};

// Implementation corresponding to Loan.cpp
Loan::Loan() {
    annualInterestRate = 9.5;
    numberOfYears = 30;
    loanAmount = 100000;
}

Loan::Loan(double rate, int years, double amount) {
    annualInterestRate = rate;
    numberOfYears = years;
    loanAmount = amount;
}

double Loan::getAnnualInterestRate() {
    return annualInterestRate;
}

int Loan::getNumberOfYears() {
    return numberOfYears;
}

double Loan::getLoanAmount() {
    return loanAmount;
}

void Loan::setAnnualInterestRate(double rate) {
    annualInterestRate = rate;
}

void Loan::setNumberOfYears(int years) {
    numberOfYears = years;
}

void Loan::setLoanAmount(double amount) {
    loanAmount = amount;
}

double Loan::getMonthlyPayment() {
    double monthlyInterestRate = annualInterestRate / 1200;
    return loanAmount * monthlyInterestRate / (1 -
      (std::pow(1 / (1 + monthlyInterestRate), numberOfYears * 12)));
}

double Loan::getTotalPayment() {
    return getMonthlyPayment() * numberOfYears * 12;
}

