int main() {
    // Fixed parameters matching Listing 9.14 sample inputs:
    // Rate: 8.25%, Years: 5, Loan Amount: 120000.95
    double annualInterestRate = 8.25;
    int numberOfYears = 5;
    double loanAmount = 120000.95;

    Loan loan(annualInterestRate, numberOfYears, loanAmount);

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "The monthly payment is " << loan.getMonthlyPayment() << "\n";
    std::cout << "The total payment is " << loan.getTotalPayment() << "\n";

    return 0;
}
